sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
        /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
        /* Optional GlideRecord */ event) {

        // Add your code here
		var hbu = new x_hccc_base.HoCBaseUtils();
		var translated_text = hbu.getTranslatedText("cmn_department", current.getDisplayValue('position_reporting_position.reports_to.department.sys_id'), "name", "fq");
		template.print(translated_text);


})(current, template, email, email_action, event);
